import weakref

class StrictType:
    """
    A descriptor that enforces type checking and optional validation at runtime.
    Uses a WeakKeyDictionary to prevent memory leaks by allowing instances 
    to be garbage collected.
    """
    def __init__(self, expected_type, validator=None):
        self.expected_type = expected_type
        self.validator = validator
        # WeakKeyDictionary ensures that the descriptor does not keep 
        # strong references to the instances it manages.
        self._values = weakref.WeakKeyDictionary()

    def __get__(self, instance, owner):
        # Return the descriptor object if accessed via the class
        if instance is None:
            return self

        try:
            return self._values[instance]
        except KeyError:
            raise AttributeError(f"'{owner.__name__}' object has no attribute managed by {self}")

    def __set__(self, instance, value):
        # 1. Check if the value matches the required type
        if not isinstance(value, self.expected_type):
            raise TypeError(f"Expected type {self.expected_type.__name__}, but got {type(value).__name__}")

        # 2. Check if the optional validator is provided and returns True
        if self.validator is not None:
            if not self.validator(value):
                raise ValueError("The provided value failed the validation check")

        # Store the validated value associated with the instance
        self._values[instance] = value

