class RegistrySingleton(type):
    _subclasses = {}
    _instances = {}

    def __new__(mcs, name, bases, attrs):
        # Create the new class
        cls = super().__new__(mcs, name, bases, attrs)

        # Automatically register the subclass in the global directory
        mcs._subclasses[name] = cls

        # Define the reset_singleton logic to be attached as a class method
        def reset_singleton(cls_obj):
            if cls_obj in mcs._instances:
                del mcs._instances[cls_obj]

        # Attach the method to the class as a classmethod
        cls.reset_singleton = classmethod(reset_singleton)

        return cls

    def __call__(cls, *args, **kwargs):
        # Enforce the singleton pattern per subclass
        if cls not in RegistrySingleton._instances:
            instance = super().__call__(*args, **kwargs)
            RegistrySingleton._instances[cls] = instance
        return RegistrySingleton._instances[cls]

